INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (71, 1, 'ILM 이 필요한 이유 알기', 'Logstash 가 로그·메트릭을 매일 Elasticsearch 에 계속 쌓습니다. 아무 조치도 하지 않으면 어떤 문제가 생길까요?', '시간이 지나면 무엇이 커질까요?', NULL, NULL, '[]', 'choice', '["인덱스가 계속 커져 검색·복구가 느려지고, 디스크가 가득 차며, 오래된 데이터가 쓸모없이 자리를 차지한다", "데이터가 자동으로 압축되어 문제없다", "ES 가 알아서 오래된 데이터를 즉시 삭제한다", "오직 Kibana 만 느려진다"]', 0, '**ILM(Index Lifecycle Management)** 은 인덱스가 태어나서 늙고 죽는 과정을 규칙으로 정해 두고 ES 가 자동으로 처리하게 합니다. 사람이 손으로 지우면 실수와 누락이 생깁니다.', NULL, NULL, NULL, NULL),
  (71, 2, 'ILM 단계 순서 놓기', '인덱스의 일생을 **젊은 단계에서 마지막 단계** 순서로 놓으세요.', '청년, 중년, 노년, 사망에 비유합니다.', NULL, NULL, '[]', 'order', '["cold", "delete", "hot", "warm"]', NULL, '**hot → warm → cold → delete** 입니다. hot 은 새 데이터가 쓰이는 단계, warm 은 더 쓰지 않지만 조회하며 용량을 줄이는 정리(shrink·forcemerge)를 하는 단계, cold 는 거의 조회하지 않아 자원을 덜 쓰는 단계, delete 는 인덱스를 통째로 지우는 단계입니다.', '[2, 3, 0, 1]', NULL, NULL, NULL),
  (71, 3, 'rollover 가 하는 일 알기', 'ILM 의 **rollover** 는 무엇을 정할까요?', '"언제 새 인덱스로 갈아탈 것인가"입니다.', NULL, NULL, '[]', 'choice', '["오래된 인덱스를 지우는 시점만 정한다", "인덱스가 일정 크기(예: 50GB)나 기간(예: 1일)에 도달하면 **새 인덱스를 만들어 거기에 쓰기 시작**하는 시점을 정한다", "샤드 수를 자동으로 늘린다", "Kibana 대시보드를 새로 만든다"]', 1, '`index-000001` 이 50GB 를 넘거나 하루가 지나면(먼저 오는 쪽) `index-000002` 로 넘어갑니다. 인덱스를 날짜·크기 단위로 쪼개 두어야 나중에 "1년 지난 것만" 인덱스 단위로 통째로 지울 수 있고, 인덱스가 너무 커지는 문제도 막습니다.', NULL, NULL, NULL, NULL),
  (71, 4, 'ILM 정책과 인덱스 템플릿의 차이', '**ILM 정책(policy)** 과 **인덱스 템플릿(template)** 의 역할 차이로 알맞은 것은 무엇일까요?', '하나는 규칙 자체, 하나는 새 인덱스가 생길 때 적용하는 설정입니다.', NULL, NULL, '[]', 'choice', '["정책이 템플릿을 대신하므로 템플릿은 필요 없다", "템플릿은 데이터를 삭제하고 정책은 복제한다", "정책은 \\"언제 rollover 하고 언제 지울지\\"의 **규칙**이고, 템플릿은 새 인덱스가 생길 때 **어떤 설정을 자동 적용할지와 어느 정책을 쓸지**를 지정한다", "둘은 같은 것이다"]', 2, '정책만 만들어서는 새 인덱스에 붙지 않습니다. 템플릿이 "이 이름 패턴의 인덱스에는 이 정책을 써라"를 연결해야 rollover 로 만들어진 새 인덱스에도 정책이 자동 적용됩니다.', NULL, NULL, NULL, NULL),
  (71, 5, '삭제는 인덱스 단위', '"1년이 지난 데이터만" 지우고 싶을 때 ES 에서 효율적인 방법은 무엇일까요?', '한 인덱스에서 일부 문서만 골라 지우는 것은 비쌉니다.', NULL, NULL, '[]', 'choice', '["큰 인덱스 하나에서 오래된 문서를 하나씩 삭제한다", "ES 를 재설치한다", "디스크를 계속 늘린다", "데이터를 애초에 날짜(기간)별 인덱스로 나눠 두고, 기간이 지난 **인덱스를 통째로 삭제**한다 (ILM 의 delete 단계)"]', 3, '문서 단위 삭제는 세그먼트에 삭제 표시만 하고 merge 때 실제 정리되므로 비용이 크고 용량이 바로 줄지 않습니다. 인덱스 단위 삭제는 파일을 통째로 지워 빠르고 확실합니다. 그래서 rollover 로 인덱스를 쪼개는 설계가 전제입니다.', NULL, NULL, NULL, NULL),
  (71, 6, '샤드와 레플리카 개념 확인', 'ES 에서 **replica** 샤드를 늘리면 얻는 것으로 알맞은 것은 무엇일까요?', '복제본의 역할을 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["노드 장애 시 데이터를 지킬 수 있고, 읽기(검색) 요청을 나눠 처리해 처리량이 늘어난다 (대신 저장 공간을 더 쓴다)", "쓰기 속도가 몇 배로 빨라진다", "디스크 사용량이 줄어든다", "인덱스가 자동으로 삭제된다"]', 0, 'replica 는 primary 의 복제본으로 장애 대비와 읽기 분산을 합니다. 같은 인덱스의 primary 와 replica 는 같은 노드에 두지 않으므로, 노드 수가 모자라면 replica 가 할당되지 못해 클러스터가 yellow 가 됩니다.', NULL, NULL, NULL, NULL),
  (71, 7, 'StorageClass·PV·PVC 구분하기', '쿠버네티스에서 Elasticsearch 의 데이터 디스크를 쓰려고 합니다. **PVC**, **PV**, **StorageClass** 의 관계로 알맞은 것은 무엇일까요?', '사용자는 "필요하다"고 요청하고, 실제 디스크는 따로 만들어집니다.', NULL, NULL, '[]', 'choice', '["PV 는 사용자의 요청서이고 PVC 는 실제 디스크이다", "PVC 는 Pod 가 \\"이만큼의 저장소가 필요하다\\"고 **요청**하는 것이고, PV 는 실제 **저장소 자원**이며, StorageClass 는 PVC 요청이 올 때 **어떤 방식으로 PV 를 자동 생성**할지 정한다", "StorageClass 는 Pod 를 삭제한다", "셋은 같은 리소스의 다른 이름이다"]', 1, '요청(PVC) → 클래스(StorageClass)가 동적으로 PV 를 만들어 → 바인딩되어 Pod 가 사용합니다. StorageClass 가 없거나 기본값이 아니면 PVC 가 Pending 으로 남습니다. NFS 를 쓰면 NFS 용 StorageClass(프로비저너)가 필요합니다.', NULL, NULL, NULL, NULL);
